import random
import time

def get_girth(adj, n, limit=6):
    # Check if there is any cycle of length <= limit
    # We can do BFS from each vertex
    for start in range(n):
        # distances and parents
        dist = {start: 0}
        q = [start]
        parent = {start: -1}

        while q:
            u = q.pop(0)
            if dist[u] >= limit // 2 + 1:
                continue
            for v in adj[u]:
                if v == parent[u]:
                    continue
                if v in dist:
                    cycle_len = dist[u] + dist[v] + 1
                    if cycle_len <= limit:
                        return cycle_len
                else:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    q.append(v)
    return 7

