from pysat.solvers import Glucose3
from pysat.card import CardEnc
import itertools
import time

def solve():
    n = 25
    solver = Glucose3()

    def var(i, j):
        if i > j:
            i, j = j, i
        return i * n + j + 1

    # Degree >= 3 and <= 6
    for i in range(n):
        edges = [var(i, j) for j in range(n) if i != j]
        cnf1 = CardEnc.atleast(lits=edges, bound=3, top_id=n*n+100)
        for clause in cnf1.clauses:
            solver.add_clause(clause)
        cnf2 = CardEnc.atmost(lits=edges, bound=6, top_id=n*n+10000)
        for clause in cnf2.clauses:
            solver.add_clause(clause)

    print("Added degree constraints")

    # 3-cycles
    for i, j, k in itertools.combinations(range(n), 3):
        solver.add_clause([-var(i, j), -var(j, k), -var(k, i)])

    # 4-cycles
    for c in itertools.combinations(range(n), 4):
        for p in itertools.permutations(c):
            if p[0] == min(p) and p[1] < p[3]:
                solver.add_clause([-var(p[0], p[1]), -var(p[1], p[2]), -var(p[2], p[3]), -var(p[3], p[0])])

    # 5-cycles
    for c in itertools.combinations(range(n), 5):
        for p in itertools.permutations(c):
            if p[0] == min(p) and p[1] < p[4]:
                solver.add_clause([-var(p[0], p[1]), -var(p[1], p[2]), -var(p[2], p[3]), -var(p[3], p[4]), -var(p[4], p[0])])

    print("Added up to 5-cycles")

    # 6-cycles
    count = 0
    for c in itertools.combinations(range(n), 6):
        for p in itertools.permutations(c):
            if p[0] == min(p) and p[1] < p[5]:
                solver.add_clause([-var(p[0], p[1]), -var(p[1], p[2]), -var(p[2], p[3]), -var(p[3], p[4]), -var(p[4], p[5]), -var(p[5], p[0])])
                count += 1
    print(f"Added {count} 6-cycles")

    start = time.time()
    res = solver.solve()
    print("Solved in", time.time() - start)
    print("Result:", res)

    if res:
        model = solver.get_model()
        edges = []
        for i in range(n):
            for j in range(i+1, n):
                if model[var(i, j) - 1] > 0:
                    edges.append((i, j))
        print(edges)

solve()

